#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    double average(vector<int>& salary) {
        int total = 0, mn = INT_MAX, mx = INT_MIN;
        for (int s : salary) {
            total += s;
            mn = min(mn, s);
            mx = max(mx, s);
        }
        return (total - mn - mx) / (double)(salary.size() - 2);
    }
};
